const crypto = require('crypto');
const net = require('net');

// Custom binary protocol parser for internal microservice communication
// Protocol: [2-byte version][4-byte header-len][4-byte body-len][header][body][32-byte HMAC]

const PROTOCOL_VERSION = 0x0102;
const MAX_BUFFER_SIZE = 0x7FFFFFFF; // 2GB max allocation
const HMAC_KEY = crypto.randomBytes(32);
const MAC_LEN = 32;

class ProtocolParser {
  constructor() {
    this.sessions = new Map();
  }

  // Validates total message size fits within safe allocation limits
  validateMessageSize(headerLen, bodyLen) {
    // Use BigInt to prevent integer overflow in size calculation
    const hLen = BigInt(headerLen);
    const bLen = BigInt(bodyLen);
    const mLen = BigInt(MAC_LEN);
    const totalLen = hLen + bLen + mLen;
    const maxSize = BigInt(MAX_BUFFER_SIZE);
    if (totalLen > maxSize) {
      return { valid: false, reason: 'Message exceeds maximum size' };
    }
    if (headerLen === 0 && bodyLen === 0) {
      return { valid: false, reason: 'Empty message' };
    }
    return { valid: true, totalLen: Number(totalLen) };
  }

  parseFrameHeader(data) {
    if (!Buffer.isBuffer(data) || data.length < 10) {
      return { error: 'Insufficient data for frame header' };
    }
    const version = data.readUInt16BE(0);
    if (version !== PROTOCOL_VERSION) {
      return { error: `Unsupported protocol version: ${version}` };
    }
    const headerLen = data.readUInt32BE(2);
    const bodyLen = data.readUInt32BE(6);
    return { version, headerLen, bodyLen };
  }

  verifyHMAC(message, receivedMac) {
    if (!Buffer.isBuffer(receivedMac) || receivedMac.length !== MAC_LEN) {
      return false;
    }
    const computed = crypto.createHmac('sha256', HMAC_KEY)
      .update(message)
      .digest();
    return crypto.timingSafeEqual(computed, receivedMac);
  }

  processMessage(rawData) {
    const frame = this.parseFrameHeader(rawData);
    if (frame.error) {
      return { success: false, error: frame.error };
    }

    const { headerLen, bodyLen } = frame;

    // Validate sizes before allocation
    const sizeCheck = this.validateMessageSize(headerLen, bodyLen);
    if (!sizeCheck.valid) {
      return { success: false, error: sizeCheck.reason };
    }

    // Calculate offsets using safe arithmetic
    const headerStart = 10;
    const bodyStart = headerStart + headerLen;
    const macStart = bodyStart + bodyLen;
    const expectedTotal = 10 + sizeCheck.totalLen;

    if (rawData.length < expectedTotal) {
      return { success: false, error: 'Incomplete message' };
    }

    // Allocate output buffer and copy data
    const outputBuffer = Buffer.allocUnsafe(sizeCheck.totalLen);
    rawData.copy(outputBuffer, 0, headerStart, headerStart + headerLen);
    rawData.copy(outputBuffer, headerLen, bodyStart, bodyStart + bodyLen);

    // Verify HMAC over header+body
    const messageData = outputBuffer.slice(0, headerLen + bodyLen);
    const receivedMac = rawData.slice(macStart, macStart + MAC_LEN);

    if (!this.verifyHMAC(messageData, receivedMac)) {
      return { success: false, error: 'HMAC verification failed' };
    }

    // Parse header as JSON
    let header;
    try {
      header = JSON.parse(outputBuffer.slice(0, headerLen).toString('utf8'));
    } catch (e) {
      return { success: false, error: 'Invalid header JSON' };
    }

    return {
      success: true,
      header,
      body: outputBuffer.slice(headerLen, headerLen + bodyLen),
      sessionId: header.sessionId || null
    };
  }
}

// TCP server using the protocol parser
const parser = new ProtocolParser();

const server = net.createServer((socket) => {
  let buffer = Buffer.alloc(0);

  socket.on('data', (chunk) => {
    buffer = Buffer.concat([buffer, chunk]);

    // Try to parse complete messages
    while (buffer.length >= 10) {
      const headerLen = buffer.readUInt32BE(2);
      const bodyLen = buffer.readUInt32BE(6);

      // Safe size calculation for frame boundary
      const totalFrameBig = BigInt(10) + BigInt(headerLen) + BigInt(bodyLen) + BigInt(MAC_LEN);
      if (totalFrameBig > BigInt(Number.MAX_SAFE_INTEGER)) {
        socket.write(JSON.stringify({ status: 'error', error: 'Frame too large' }) + '\n');
        socket.destroy();
        return;
      }

      // Reject frames that exceed the allocation limit BEFORE buffering the
      // full frame, to prevent per-connection memory-exhaustion DoS.
      const maxFrameBig = BigInt(10) + BigInt(MAX_BUFFER_SIZE);
      if (totalFrameBig > maxFrameBig) {
        socket.write(JSON.stringify({ status: 'error', error: 'Frame exceeds maximum size' }) + '\n');
        socket.destroy();
        return;
      }

      const totalFrameSize = Number(totalFrameBig);

      if (buffer.length < totalFrameSize) break;

      const messageData = buffer.slice(0, totalFrameSize);
      const result = parser.processMessage(messageData);

      if (result.success) {
        socket.write(JSON.stringify({ status: 'ok', sessionId: result.sessionId }) + '\n');
      } else {
        socket.write(JSON.stringify({ status: 'error', error: result.error }) + '\n');
      }

      buffer = buffer.slice(totalFrameSize);
    }
  });

  socket.on('error', () => socket.destroy());
});

server.listen(9000, '127.0.0.1');

module.exports = { ProtocolParser, server };
